"use client";
import { useEffect, useId, useRef, useState } from "react";
import "./glass-surface.css";
import "./glass-controls.css";

const Tick = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 12.5l4 4 8-9" />
  </svg>
);

/* ---------- Liquid glass ----------
   While held, a thumb turns into a clear glass drop. Inside it sits a
   magnified copy of the track (the "lens"), so the track looks bent and
   enlarged through the glass. Plain CSS, so it works in every browser. */

/* "held" while a pointer is down; "settle" plays a short wobble after */
function useGlass(ms = 520) {
  const [held, setHeld] = useState(false);
  const [settle, setSettle] = useState(false);
  const t = useRef(0);
  useEffect(() => () => clearTimeout(t.current), []);
  const release = () => {
    setHeld(false);
    setSettle(true);
    clearTimeout(t.current);
    t.current = setTimeout(() => setSettle(false), ms);
  };
  const pulse = () => {
    setHeld(true);
    clearTimeout(t.current);
    t.current = setTimeout(release, 240);
  };
  return { held, settle, hold: () => { clearTimeout(t.current); setSettle(false); setHeld(true); }, release, pulse };
}

/** GlassSwitch: checked, onChange(next), label. Tap it, or drag the thumb. */
export function GlassSwitch({ checked = false, onChange, label, disabled = false, ...rest }) {
  const g = useGlass();
  const drag = useRef(null);
  const set = (v) => onChange && v !== checked && onChange(v);
  return (
    <button
      type="button"
      className="gsw"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      data-held={g.held ? "" : undefined}
      data-settle={g.settle ? "" : undefined}
      onPointerDown={(e) => {
        if (disabled || e.button !== 0) return;
        drag.current = { x: e.clientX, moved: false };
        e.currentTarget.setPointerCapture(e.pointerId);
        g.hold();
      }}
      onPointerMove={(e) => {
        const d = drag.current;
        if (!d) return;
        const dx = e.clientX - d.x;
        if (Math.abs(dx) > 6) { d.moved = true; set(dx > 0); }
      }}
      onPointerUp={() => { if (drag.current) g.release(); }}
      onPointerCancel={() => { drag.current = null; g.release(); }}
      onClick={(e) => {
        const d = drag.current;
        drag.current = null;
        if (d && d.moved) return; /* a drag already chose the side */
        if (e.detail === 0) g.pulse(); /* keyboard */
        onChange && onChange(!checked);
      }}
      {...rest}
    >
      <span className="gsw-track"><span className="gsw-thumb"><span className="g-lens" /></span></span>
      {label && <span>{label}</span>}
    </button>
  );
}

/** GlassCheckbox: checked, onChange(next), label, hint */
export function GlassCheckbox({ checked = false, onChange, label, hint, disabled = false }) {
  return (
    <label className="gopt" data-disabled={disabled ? "" : undefined}>
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange && onChange(e.target.checked)} />
      <span className="gck" aria-hidden="true"><Tick /></span>
      <span className="gopt-text">
        <span>{label}</span>
        {hint && <span className="gopt-hint">{hint}</span>}
      </span>
    </label>
  );
}

/**
 * GlassCheckboxGroup: pick any number.
 * options  [{ value, label, hint?, disabled? }]
 * value    array of chosen values; onChange(nextArray)
 */
export function GlassCheckboxGroup({ label, options, value = [], onChange }) {
  const toggle = (v, on) => onChange && onChange(on ? [...value, v] : value.filter((x) => x !== v));
  return (
    <fieldset className="ggroup">
      {label && <legend className="gfield-label">{label}</legend>}
      {options.map((o) => (
        <GlassCheckbox key={o.value} label={o.label} hint={o.hint} disabled={o.disabled} checked={value.includes(o.value)} onChange={(on) => toggle(o.value, on)} />
      ))}
    </fieldset>
  );
}

/**
 * GlassRadioGroup: pick exactly one.
 * options  [{ value, label, hint?, disabled? }]
 * value, onChange(value)
 */
export function GlassRadioGroup({ label, options, value, onChange }) {
  const name = useId();
  return (
    <fieldset className="ggroup">
      {label && <legend className="gfield-label">{label}</legend>}
      {options.map((o) => (
        <label key={o.value} className="gopt" data-disabled={o.disabled ? "" : undefined}>
          <input type="radio" name={name} checked={value === o.value} disabled={o.disabled} onChange={() => onChange && onChange(o.value)} />
          <span className="gck" data-round="" aria-hidden="true"><span className="gck-dot" /></span>
          <span className="gopt-text">
            <span>{o.label}</span>
            {o.hint && <span className="gopt-hint">{o.hint}</span>}
          </span>
        </label>
      ))}
    </fieldset>
  );
}

/** GlassSlider: value, onChange(number), min, max, step, label, unit */
// Sound comes from glass-sound.jsx when it is loaded and switched on.
let slLast = 0;
const slSound = () => (typeof window !== "undefined" && window.glassSound) || null;
function slWake() { const g = slSound(); g && g.wake(); }
// A short, soft "tok" whose pitch follows the position: low on the left, bright on the right
function slTick(p, edge) {
  const now = performance.now(); if (now - slLast < 28 && !edge) return; slLast = now;
  const gs = slSound(); if (gs && !gs.get().on) return;
  try {
    const ctx = gs && gs.context(), out = gs && gs.output();
    if (ctx && out && ctx.state === "running") {
      const t = ctx.currentTime, o = ctx.createOscillator(), g = ctx.createGain();
      o.type = "sine"; o.frequency.setValueAtTime(380 + p * 620, t); o.frequency.exponentialRampToValueAtTime(260 + p * 420, t + 0.05);
      g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(edge ? 0.2 : 0.11, t + 0.004); g.gain.exponentialRampToValueAtTime(0.0001, t + (edge ? 0.12 : 0.06));
      o.connect(g).connect(out); o.start(t); o.stop(t + 0.14);
    }
  } catch (e) {}
  try { navigator.vibrate && navigator.vibrate(edge ? 10 : 3); } catch (e) {}
}
export function GlassSlider({ value = 0, onChange, min = 0, max = 100, step = 1, label, unit = "", showValue = true, sound = true }) {
  const id = useId();
  const p = (value - min) / (max - min);
  const g = useGlass();
  // Dots mark the steps: every step when there are few, otherwise ten even marks
  const n = Math.round((max - min) / step);
  const marks = n <= 12 ? n : 10;
  return (
    <div className="gsl">
      {(label || showValue) && (
        <div className="gsl-head">
          <label htmlFor={id}>{label}</label>
          {showValue && <span>{value}{unit}</span>}
        </div>
      )}
      {/* The real range input sits on top, invisible, so dragging and the keyboard work as normal */}
      <div className="gsl-rail" data-held={g.held ? "" : undefined} data-settle={g.settle ? "" : undefined} style={{ "--gsl-p": p }}>
        <span className="gsl-track">
          <span className="gsl-fill" />
          <span className="gsl-dots" aria-hidden="true">{Array.from({ length: marks + 1 }, (_, i) => <i key={i} style={{ "--k": i / marks }} data-on={i / marks <= p + 0.001 ? "" : undefined} />)}</span>
        </span>
        <span className="gsl-thumb" aria-hidden="true"><span className="g-lens" /></span>
        <input
          id={id}
          className="gsl-input"
          type="range"
          min={min}
          max={max}
          step={step}
          value={value}
          onChange={(e) => { const v = Number(e.target.value); if (sound && v !== value) slTick((v - min) / (max - min || 1), v === min || v === max); onChange && onChange(v); }}
          onPointerDown={(e) => { if (sound) slWake(); g.hold(e); }}
          onPointerUp={g.release}
          onPointerCancel={g.release}
          onKeyDown={(e) => { if (e.key.startsWith("Arrow") || e.key === "Home" || e.key === "End" || e.key.startsWith("Page")) g.pulse(); }}
        />
      </div>
    </div>
  );
}

/* Switch, checkbox, radio and slider. */
.ggroup { display: flex; flex-direction: column; gap: 10px; min-width: 0; margin: 0; padding: 0; border: 0; }
.ggroup > legend { padding: 0; margin-bottom: 2px; }
.gopt { display: flex; align-items: flex-start; gap: 10px; font-size: 14px; line-height: 20px; color: var(--glass-fg); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.gopt[data-disabled] { opacity: 0.45; cursor: not-allowed; }
.gopt-text { display: flex; flex-direction: column; min-width: 0; }
.gopt-hint { font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.6); }
.gopt input { position: absolute; width: 1px; height: 1px; opacity: 0; margin: 0; }

/* ---------- Checkbox and radio ---------- */
.gck {
  position: relative;
  flex: none;
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  color: var(--glass-on-tint);
  background: #fff;
  box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.22), 0 1px 2px rgb(var(--glass-shadow) / 0.06);
  transition: background 0.16s, box-shadow 0.16s, transform 0.16s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.gck[data-round] { border-radius: 50%; }
/* Press: the box swells into a clear glass bead, then springs back */
.gck { transition: background 0.16s, box-shadow 0.16s, transform 0.42s cubic-bezier(0.34, 1.56, 0.64, 1); }
.gck::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transform: scale(0.8);
  background: radial-gradient(120% 90% at 30% 20%, rgb(255 255 255 / 0.85), rgb(255 255 255 / 0.15) 55%, rgb(255 255 255 / 0.05));
  -webkit-backdrop-filter: blur(1px) saturate(1.9) brightness(1.1);
  backdrop-filter: blur(1px) saturate(1.9) brightness(1.1);
  box-shadow: inset 0 0 0 0.5px rgb(255 255 255 / 0.9), inset 0 -2px 4px rgb(var(--glass-shadow) / 0.12), 0 4px 10px -2px rgb(var(--glass-shadow) / 0.22);
  transition: opacity 0.25s, transform 0.42s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.gopt:active .gck { transform: scale(1.18); transition-duration: 0.16s, 0.16s, 0.18s; }
.gopt:active .gck::after { opacity: 1; transform: scale(1); }
@media (prefers-reduced-motion: reduce) { .gck, .gck::after { transition: none; } .gopt:active .gck { transform: none; } }
.gopt input:checked + .gck {
  background: var(--glass-tint);
  box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.12), 0 2px 5px -1px color-mix(in srgb, var(--glass-tint) 55%, transparent);
}
.gopt input:focus-visible + .gck { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: 2px; }
.gck svg { width: 14px; height: 14px; }
/* The tick draws itself in */
.gck path { stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset 0.22s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gopt input:checked + .gck path { stroke-dashoffset: 0; }
.gck-dot { width: 8px; height: 8px; border-radius: 50%; background: currentColor; transform: scale(0); transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gopt input:checked + .gck .gck-dot { transform: scale(1); }

/* ---------- Switch ---------- */
.gsw { touch-action: pan-y; display: inline-flex; align-items: center; gap: 12px; padding: 0; border: 0; background: none; font: inherit; font-size: 14px; color: var(--glass-fg); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.gsw:disabled { opacity: 0.45; cursor: not-allowed; }
.gsw-track {
  position: relative;
  flex: none;
  width: 44px;
  height: 26px;
  border-radius: 999px;
  background: rgb(var(--glass-shadow) / 0.16);
  box-shadow: inset 0 1px 2px rgb(var(--glass-shadow) / 0.12);
  transition: background 0.22s;
}
.gsw-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 1px 1px rgb(var(--glass-shadow) / 0.12), 0 3px 6px -1px rgb(var(--glass-shadow) / 0.22);
  transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1), width 0.18s;
}
.gsw[aria-checked="true"] .gsw-track { background: var(--glass-tint); }
.gsw[aria-checked="true"] .gsw-thumb { transform: translateX(18px); }
.gsw:focus-visible { outline: none; }
.gsw:focus-visible .gsw-track { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: 2px; }

/* ---------- Slider ---------- */
.gsl { display: flex; flex-direction: column; gap: 6px; min-width: 0; color: var(--glass-fg); }
.gsl-head { display: flex; justify-content: space-between; gap: 12px; font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums; }
/* A soft pill with step dots; the fill runs to a white thumb that sits inside it */
.gsl-rail { --gsl-fill: var(--glass-tint); --gsl-t: 32px; --gsl-in: 4px; --gsl-w: calc(100% - var(--gsl-in) * 2 - var(--gsl-t)); position: relative; display: flex; align-items: center; height: 40px; }
.gsl-track { position: absolute; inset: 0; overflow: hidden; border-radius: 999px; background: var(--gsl-bg, rgb(var(--glass-shadow) / 0.07)); box-shadow: inset 0 1px 2px rgb(var(--glass-shadow) / 0.06); }
.gsl-fill { position: absolute; left: 0; top: 0; bottom: 0; display: block; width: calc(var(--gsl-in) * 2 + var(--gsl-t) + var(--gsl-w) * var(--gsl-p)); border-radius: inherit; background: linear-gradient(180deg, rgb(255 255 255 / 0.22), transparent 60%), var(--gsl-fill); transition: background-color 0.2s; }
.gsl-dots { position: absolute; inset: 0; pointer-events: none; }
.gsl-dots i { position: absolute; top: 50%; left: calc(var(--gsl-in) + var(--gsl-t) / 2 + var(--gsl-w) * var(--k)); width: 4px; height: 4px; margin: -2px 0 0 -2px; border-radius: 50%; background: rgb(var(--glass-shadow) / 0.22); transition: background-color 0.2s, scale 0.3s cubic-bezier(0.3, 1.5, 0.5, 1); }
.gsl-dots i[data-on] { background: color-mix(in srgb, var(--glass-on-tint, #fff) 60%, transparent); }
.gsl-rail:hover .gsl-dots i { scale: 1.25; }
.gsl-head span { color: rgb(var(--glass-shadow) / 0.6); }
.gsl-thumb {
  position: absolute;
  left: calc(var(--gsl-in) + var(--gsl-w) * var(--gsl-p));
  width: var(--gsl-t);
  height: var(--gsl-t);
  border-radius: 999px;
  pointer-events: none;
  background: #fff;
  box-shadow: 0 0 0 0.5px rgb(var(--glass-shadow) / 0.1), 0 2px 4px rgb(var(--glass-shadow) / 0.14), 0 6px 14px -4px rgb(var(--glass-shadow) / 0.3);
  transition: scale 0.42s cubic-bezier(0.34, 1.45, 0.5, 1), background 0.22s, box-shadow 0.22s;
}
.gsl-input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.gsl-rail:has(.gsl-input:focus-visible) .gsl-thumb { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: 2px; }

/* ---------- Liquid glass ----------
   Hold a switch or slider thumb and it lifts into a clear glass drop: it
   grows past the track, the track shows through it bent by the lens, and the
   rim catches light. Let go and it wobbles back to a solid bead, like iOS. */
.gsw-thumb, .gsl-thumb {
  transition:
    transform 0.5s cubic-bezier(0.34, 1.35, 0.5, 1),
    width 0.42s cubic-bezier(0.34, 1.5, 0.5, 1),
    height 0.42s cubic-bezier(0.34, 1.5, 0.5, 1),
    top 0.42s cubic-bezier(0.34, 1.5, 0.5, 1),
    left 0.42s cubic-bezier(0.34, 1.5, 0.5, 1),
    margin 0.42s cubic-bezier(0.34, 1.5, 0.5, 1),
    background 0.28s, box-shadow 0.28s;
}
.gsl-thumb { transition-property: width, height, margin, background, box-shadow; }
.gsw[data-held] .gsw-thumb,
.gsl-rail[data-held] .gsl-thumb {
  z-index: 1;
  background:
    radial-gradient(70% 45% at 50% 8%, rgb(255 255 255 / 0.55), transparent 70%),
    radial-gradient(60% 40% at 50% 100%, rgb(255 255 255 / 0.28), transparent 70%),
    rgb(255 255 255 / 0.04);
  -webkit-backdrop-filter: blur(0.5px) saturate(1.8) brightness(1.08);
  backdrop-filter: blur(0.5px) saturate(1.8) brightness(1.08);
  box-shadow:
    inset 0 0 0 0.5px rgb(255 255 255 / 0.95),
    inset 1px 1.5px 1px rgb(255 255 255 / 0.9),
    inset -1px -1.5px 2px rgb(255 255 255 / 0.55),
    inset 0 -4px 8px rgb(var(--glass-shadow) / 0.1),
    0 0 0 0.5px rgb(var(--glass-shadow) / 0.12),
    0 10px 22px -8px rgb(var(--glass-shadow) / 0.38);
}
/* The lens: the track seen through the drop, enlarged, with its ends
   rounded off where the glass curves away */
.g-lens {
  position: absolute;
  z-index: -1;
  inset: 2px;
  border-radius: inherit;
  overflow: hidden;
  opacity: 0;
  transition: opacity 0.2s;
  pointer-events: none;
}
.g-lens::before {
  content: "";
  position: absolute;
  left: -6%;
  right: -6%;
  top: 50%;
  translate: 0 -50%;
  border-radius: 999px;
  filter: saturate(1.25);
  -webkit-mask-image: radial-gradient(closest-side, #000 72%, transparent);
  mask-image: radial-gradient(closest-side, #000 72%, transparent);
}
.gsw-thumb, .gsl-thumb { isolation: isolate; }
.gsw[data-held] .g-lens, .gsl-rail[data-held] .g-lens { opacity: 1; }
/* Slider: the fill ends right under the middle of the drop */
.gsl-thumb .g-lens::before {
  height: 13px;
  background: linear-gradient(90deg, var(--gsl-fill) 50%, var(--gsl-bg, rgb(var(--glass-shadow) / 0.2)) 50%);
}
/* Switch: the track colour, magnified to fill most of the drop */
.gsw-thumb .g-lens::before { height: 84%; background: var(--gsw-bg, rgb(var(--glass-shadow) / 0.22)); }
.gsw[aria-checked="true"] .gsw-thumb .g-lens::before { background: var(--gsw-on, var(--glass-tint)); }
/* Held: the drop swells past the track. It grows in real size, not with a
   transform, so the lens stays lined up with what is behind it. */
.gsw[data-held] .gsw-thumb { width: 36px; height: 30px; top: -2px; left: -5px; }
.gsl-rail[data-held] .gsl-thumb { width: 46px; height: 44px; margin-left: -7px; }
/* Let go: a short liquid wobble before it sets */
.gsw[data-settle] .gsw-thumb, .gsl-rail[data-settle] .gsl-thumb { animation: g-wobble 0.52s cubic-bezier(0.3, 0.7, 0.4, 1); }
@keyframes g-wobble {
  0% { scale: 1 1; }
  30% { scale: 1.1 0.9; }
  55% { scale: 0.95 1.05; }
  80% { scale: 1.02 0.99; }
  100% { scale: 1 1; }
}

@media (prefers-reduced-motion: reduce) {
  .gck, .gck path, .gck-dot, .gsw-thumb, .gsw-track, .gsl-thumb { transition: none; animation: none !important; }
  .gsw[data-held] .gsw-thumb { width: 22px; height: 22px; top: 2px; left: 2px; }
  .gsl-rail[data-held] .gsl-thumb { width: var(--gsl-t); height: var(--gsl-t); margin-left: 0; }
}

/* ---------- Frost: the controls in frosted glass ----------
   Applies with data-glass-tint="frost", the Mist theme's default. */
[data-glass-tint="frost"] {
  --fr-glass: linear-gradient(180deg, #f1f3f7, #cfd6e1 52%, #dfe4ec);
  --fr-skin: inset 0 1px 0 #fff, inset 0 -1px 0 rgb(255 255 255 / 0.85), inset 0 0 8px rgb(255 255 255 / 0.45), 0 0 0 1px rgb(70 82 104 / 0.22);
  --fr-well: inset 0 1px 3px rgb(60 72 98 / 0.2), 0 0 0 1px rgb(70 82 104 / 0.22);
  /* "On" is a deeper frost, so it never reads as off */
  --fr-on: linear-gradient(180deg, #d6dbe4, #9ea8b8 55%, #b7c0cd);
  --fr-bead: radial-gradient(60% 45% at 40% 22%, #fff, transparent 72%), linear-gradient(180deg, #ffffff, #e7ebf1);
  --fr-bead-skin: inset 0 0 0 1px rgb(255 255 255 / 0.95), 0 0 0 0.5px rgb(70 82 104 / 0.28), 0 2px 5px rgb(60 72 98 / 0.28);
}
/* Switch: a recessed groove that fills with frosted glass */
[data-glass-tint="frost"] .gsw-track { background: linear-gradient(180deg, rgb(214 220 230 / 0.7), rgb(238 241 246 / 0.9)); box-shadow: var(--fr-well); }
[data-glass-tint="frost"] .gsw[aria-checked="true"] .gsw-track { background: var(--fr-on); box-shadow: var(--fr-skin), 0 3px 8px -3px rgb(60 72 98 / 0.35); }
[data-glass-tint="frost"] .gsw-thumb { background: var(--fr-bead); box-shadow: var(--fr-bead-skin); }
/* Checkbox and radio */
[data-glass-tint="frost"] .gck { color: #353d4d; background: linear-gradient(180deg, #f3f5f8, #ffffff); box-shadow: var(--fr-well); }
[data-glass-tint="frost"] .gopt input:checked + .gck { color: #1f2633; background: var(--fr-on); box-shadow: var(--fr-skin), 0 2px 5px -2px rgb(60 72 98 / 0.35); }
/* Slider: a glass fill with a sheen on top, and a glass bead to drag */
[data-glass-tint="frost"] .gsl-track { background: rgb(60 72 98 / 0.08); box-shadow: var(--fr-well); }
[data-glass-tint="frost"] .gsl-rail { --gsl-fill: #a3adbd; --gsl-bg: #e8ebf0; }
[data-glass-tint="frost"] .gsl-dots i[data-on] { background: rgb(255 255 255 / 0.75); }
[data-glass-tint="frost"] .gsw { --gsw-bg: #dfe4ec; --gsw-on: linear-gradient(180deg, #c4cbd7, #8e99ab 55%, #a9b3c2); }
[data-glass-tint="frost"] .gsl-fill { background: linear-gradient(180deg, rgb(255 255 255 / 0.85), transparent 70%), #a3adbd; }
[data-glass-tint="frost"] .gsl-thumb { background: var(--fr-bead); box-shadow: var(--fr-bead-skin), 0 6px 12px -4px rgb(60 72 98 / 0.3); }
/* Progress bars and carousel dots follow */
[data-glass-tint="frost"] .gpr-track { --gpr-track: rgb(60 72 98 / 0.1); box-shadow: var(--fr-well); }
[data-glass-tint="frost"] .gpr[data-accent] .gpr-fill { background: var(--fr-glass); box-shadow: var(--fr-skin); }
[data-glass-tint="frost"] .gdot[aria-current="true"] { background: var(--fr-glass); box-shadow: var(--fr-skin); }

import * as React from "react";

